public static boolean isValidUrl(String url) {
    try {
        java.net.URI uri = new java.net.URI(url);
        String scheme = uri.getScheme();
        return "http".equals(scheme) || "https".equals(scheme);
    } catch (Exception e) {
        return false;
    }
}

