import re

# IPv4: four octets, each 0-255:
IPV4_RE = re.compile(
    r'^((25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)\\.)'
    r'{3}(25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)$'
)

def is_valid_ipv4(addr: str) -> bool:
    return bool(IPV4_RE.match(addr.strip()))

# Extract IPv4 addresses from text:
def extract_ipv4(text: str) -> list[str]:
    no_anchors = re.compile(
        r'(?<!\\d)((25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)\\.)'
        r'{3}(25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)(?!\\d)'
    )
    return no_anchors.findall(text)

# Examples:
print(is_valid_ipv4('192.168.1.1'))   # True
print(is_valid_ipv4('999.1.1.1'))     # False

